import { z } from "zod";

export const videoInfoRequestSchema = z.strictObject({
  url: z.string().min(1).max(4096),
});

export const createDownloadRequestSchema = z.strictObject({
  analysisId: z.uuid(),
  // Option ids are generated by the server: "v2160-mp4", "v0-mov", "a-m4a", "a-mp3", …
  optionId: z.string().regex(/^(v\d{1,5}-[a-z0-9]{1,8}|a-[a-z0-9]{1,8})$/),
});

export const createMediaDownloadRequestSchema = z.strictObject({
  analysisId: z.uuid(),
  // 1-based positions of the chosen items in the post.
  items: z.array(z.int().min(1).max(1000)).min(1).max(100),
});

export const jobIdSchema = z.uuid();
